{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-SaY877/src/errors.js","content":"/**
 * A parse failure tied to a specific reason text. The document parser
 * catches these and stamps them with the line number where they occurred.
 */
export class LineError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}

/** A `LineError` stamped with the 1-based line number it occurred on. */
export class DocumentError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}
"}

