{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-SaY877/src/nodes.js","content":"/**
 * The value tree the parser builds. Every node carries a `kind` so `keys`
 * mode can report a type and so `json` mode knows how to render it; a table
 * node also tracks whether a `[name]` header has already made it current,
 * and an array node tracks whether it is an array of tables (as opposed to
 * a plain value array), since the two are rejected differently.
 */

export function stringNode(value) {
  return { kind: 'string', value }
}

export function integerNode(value) {
  return { kind: 'integer', value }
}

export function floatNode(value) {
  return { kind: 'float', value }
}

export function booleanNode(value) {
  return { kind: 'boolean', value }
}

export function arrayNode(items = [], isArrayOfTables = false) {
  return { kind: 'array', items, isArrayOfTables }
}

export function tableNode() {
  return { kind: 'table', keys: new Map(), explicit: false }
}

/** Joins decoded key names into the dotted path text used in messages. */
export function buildPath(names) {
  return names.join('.')
}
"}

