{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-SaY877/src/scanner.js","content":"/**
 * Low-level, position-based scanning for a single line: whitespace and
 * comment handling, names, strings, and values (including arrays and
 * inline tables, which may nest). Every function takes a line string and
 * an index into it, and returns `{ ..., next }` where `next` is the index
 * just past what was consumed, or throws a `LineError`.
 */
import { LineError } from './errors.js'
import { stringNode, integerNode, floatNode, booleanNode, arrayNode, tableNode } from './nodes.js'

const DIGITS = '\\d+(?:_\\d+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

export function skipWS(s, i) {
  while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++
  return i
}

/**
 * Skips whitespace and reports where the next meaningful character is, or
 * -1 if the rest of the line is empty or a comment (which is the same as
 * empty, since it is ignored).
 */
export function significant(s, i) {
  i = skipWS(s, i)
  if (i >= s.length) return -1
  if (s[i] === '#' || s[i] === ';') return -1
  return i
}

export function parseBasicString(s, i) {
  let j = i + 1
  let out = ''
  while (true) {
    if (j >= s.length) throw new LineError('unterminated string')
    const c = s[j]
    if (c === '"') {
      j++
      break
    }
    if (c === '\\') {
      const e = s[j + 1]
      if (e === undefined) throw new LineError('unterminated string')
      switch (e) {
        case '"':
          out += '"'
          j += 2
          break
        case '\\':
          out += '\\'
          j += 2
          break
        case 'n':
          out += '\n'
          j += 2
          break
        case 't':
          out += '\t'
          j += 2
          break
        case 'r':
          out += '\r'
          j += 2
          break
        case '0':
          out += '\0'
          j += 2
          break
        case 'u': {
          const hex = s.slice(j + 2, j + 6)
          if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
            out += String.fromCharCode(parseInt(hex, 16))
            j += 6
          } else {
            throw new LineError('invalid escape \\u')
          }
          break
        }
        default:
          throw new LineError(`invalid escape \\${e}`)
      }
      continue
    }
    out += c
    j++
  }
  return { value: out, next: j }
}

export function parseLiteralString(s, i) {
  let j = i + 1
  while (true) {
    if (j >= s.length) throw new LineError('unterminated string')
    if (s[j] === "'") {
      j++
      break
    }
    j++
  }
  return { value: s.slice(i + 1, j - 1), next: j }
}

function parseName(s, i) {
  const c = s[i]
  if (c === '"') return parseBasicString(s, i)
  if (c === "'") return parseLiteralString(s, i)
  let j = i
  while (j < s.length && /[A-Za-z0-9_-]/.test(s[j])) j++
  if (j === i) throw new LineError('expected a name')
  return { value: s.slice(i, j), next: j }
}

/** Parses `name ( '.' name )*`, allowing whitespace around each dot. */
export function parseDottedName(s, i) {
  const names = []
  while (true) {
    const sig = significant(s, i)
    if (sig === -1) throw new LineError('expected a name')
    const { value, next } = parseName(s, sig)
    names.push(value)
    i = next
    const sig2 = significant(s, i)
    if (sig2 !== -1 && s[sig2] === '.') {
      i = sig2 + 1
      continue
    }
    break
  }
  return { names, next: i }
}

/** Parses a value at a position already known to hold a real character. */
export function parseValue(s, i) {
  const c = s[i]
  if (c === ',' || c === ']' || c === '}') throw new LineError('expected a value')
  if (c === '"') {
    const { value, next } = parseBasicString(s, i)
    return { node: stringNode(value), next }
  }
  if (c === "'") {
    const { value, next } = parseLiteralString(s, i)
    return { node: stringNode(value), next }
  }
  if (c === '[') return parseArray(s, i)
  if (c === '{') return parseInlineTable(s, i)

  let j = i
  while (j < s.length && !' \t,]}'.includes(s[j])) j++
  const word = s.slice(i, j)
  if (word === 'true') return { node: booleanNode(true), next: j }
  if (word === 'false') return { node: booleanNode(false), next: j }
  if (INT_RE.test(word)) return { node: integerNode(Number(word.replace(/_/g, ''))), next: j }
  if (FLOAT_RE.test(word) && /[.eE]/.test(word)) {
    return { node: floatNode(Number(word.replace(/_/g, ''))), next: j }
  }
  throw new LineError(`invalid value ${word}`)
}

function parseArray(s, i) {
  let j = i + 1
  const items = []
  while (true) {
    let sig = significant(s, j)
    if (sig === -1) throw new LineError('unterminated array')
    if (s[sig] === ']') {
      j = sig + 1
      break
    }
    const { node, next } = parseValue(s, sig)
    items.push(node)
    j = next
    sig = significant(s, j)
    if (sig === -1) throw new LineError('unterminated array')
    if (s[sig] === ',') {
      j = sig + 1
      continue
    }
    if (s[sig] === ']') {
      j = sig + 1
      break
    }
    throw new LineError('trailing text after a value')
  }
  return { node: arrayNode(items), next: j }
}

function parseInlineTable(s, i) {
  let j = i + 1
  const table = tableNode()
  let sig = significant(s, j)
  if (sig === -1) throw new LineError('unterminated inline table')
  if (s[sig] === '}') return { node: table, next: sig + 1 }

  while (true) {
    sig = significant(s, j)
    if (sig === -1) throw new LineError('unterminated inline table')
    const { names, next: n1 } = parseDottedName(s, sig)
    j = n1

    const sigEq = significant(s, j)
    if (sigEq === -1) throw new LineError('unterminated inline table')
    if (s[sigEq] !== '=') throw new LineError('expected = in an inline table')
    j = sigEq + 1

    const sigVal = significant(s, j)
    if (sigVal === -1) throw new LineError('unterminated inline table')
    const { node, next: n2 } = parseValue(s, sigVal)
    j = n2

    assignInto(table, names, node, [])

    const sigSep = significant(s, j)
    if (sigSep === -1) throw new LineError('unterminated inline table')
    if (s[sigSep] === ',') {
      j = sigSep + 1
      continue
    }
    if (s[sigSep] === '}') {
      j = sigSep + 1
      break
    }
    throw new LineError('trailing text after a value')
  }
  return { node: table, next: j }
}

/**
 * Walks (creating as needed) all but the last of `names` starting at
 * `node`, then assigns the last name to `value`. `pathPrefix` is the
 * absolute path (from the document root) to `node`, used only for error
 * messages. Shared by inline-table pairs and top-level key = value lines.
 */
export function assignInto(node, names, value, pathPrefix) {
  let container = node
  for (let k = 0; k < names.length - 1; k++) {
    const name = names[k]
    const path = [...pathPrefix, ...names.slice(0, k + 1)].join('.')
    if (!container.keys.has(name)) {
      const t = tableNode()
      container.keys.set(name, t)
      container = t
    } else {
      const existing = container.keys.get(name)
      if (existing.kind === 'array' && existing.isArrayOfTables) {
        container = existing.items[existing.items.length - 1]
      } else if (existing.kind === 'table') {
        container = existing
      } else {
        throw new LineError(`${path} is not a table`)
      }
    }
  }
  const lastName = names[names.length - 1]
  const fullPath = [...pathPrefix, ...names].join('.')
  if (container.keys.has(lastName)) {
    throw new LineError(`key ${fullPath} is defined twice`)
  }
  container.keys.set(lastName, value)
}
"}

