 * Turns the parsed table tree into the two output formats: canonical JSON
 * and the flat `<path> <type>` listing.
 */

function sortedKeys(map) {
  return Array.from(map.keys()).sort()
}

/**
 * Builds a plain JSON-ready value from a node tree, with object members
 * inserted in ascending key order so `JSON.stringify` preserves that order.
 * A null-prototype object is used so a key literally named `__proto__`
 * becomes an own property instead of reassigning the prototype.
 */
export function toPlain(node) {
  switch (node.kind) {
    case 'table': {
      const obj = Object.create(null)
      for (const k of sortedKeys(node.keys)) obj[k] = toPlain(node.keys.get(k))
      return obj
    }
    case 'array':
      return node.items.map(toPlain)
    default:
      return node.value
  }
}

export function renderJson(root) {
  return JSON.stringify(toPlain(root), null, 2) + '\n'
}

function walkKeys(node, path, lines) {
  lines.push(`${path} ${node.kind}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.keys)) {
      walkKeys(node.keys.get(k), path ? `${path}.${k}` : k, lines)
    }
  } else if (node.kind === 'array') {
    node.items.forEach((item, idx) => walkKeys(item, `${path}[${idx}]`, lines))
  }
}

export function renderKeys(root) {
  const lines = []
  for (const k of sortedKeys(root.keys)) walkKeys(root.keys.get(k), k, lines)
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

