 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { parseDocument } from './document.js'
import { renderJson, renderKeys } from './render.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = await readStdin()

  let doc
  try {
    doc = parseDocument(input)
  } catch (e) {
    if (e && typeof e.line === 'number') {
      process.stderr.write(`error: line ${e.line}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  const output = mode === 'json' ? renderJson(doc.root) : renderKeys(doc.root)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

